  ('dsa-632', 'user-default', 'goal-dsa', 'Smallest Range Covering Elements from K Lists', 'Heap', 'Hard', 'https://leetcode.com/problems/smallest-range-covering-elements-from-k-lists', 40, false, NOW(), NULL, false, NULL, NULL),
  ('mla-1-1-1', 'user-default', 'goal-aws', 'Data Ingestion from Object & Block Storage (Amazon S3 & Amazon EBS)', 'Domain 1: Data Preparation', 'Easy', 'https://docs.aws.amazon.com/sagemaker/latest/dg/model-access-training-data.html', 25, false, NOW(), '1.1 Collect & Store Data', true, 'Understand S3 storage tiers, partitioning, S3 event notifications, and EBS volume attachment for SageMaker notebook and training environments.', 'Exam Tip: Amazon S3 is the primary data lake store. For unpredictable access, choose S3 Intelligent-Tiering. Amazon EBS provides the fastest single-instance IOPS for local notebook development, but does NOT support multi-node shared access across distributed clusters.'),
  ('mla-1-1-2', 'user-default', 'goal-aws', 'Shared File Systems for Distributed Training (Amazon EFS & FSx for Lustre)', 'Domain 1: Data Preparation', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/model-access-training-data.html#model-access-training-data-fsx', 30, false, NOW(), '1.1 Collect & Store Data', true, 'Compare EFS and FSx for Lustre for feeding large-scale training datasets directly into multi-node SageMaker training clusters without S3 download latency.', 'Exam Rule: When training on massive computer vision or multimodal datasets across distributed GPU clusters, ALWAYS select Amazon FSx for Lustre linked directly to S3. It streams hundreds of GB/s and avoids multi-hour data download bottlenecks before training starts.'),
  ('mla-1-1-3', 'user-default', 'goal-aws', 'Database Ingestion (Amazon RDS, Amazon DynamoDB, Amazon DocumentDB, AWS DMS)', 'Domain 1: Data Preparation', 'Medium', 'https://docs.aws.amazon.com/dms/latest/userguide/Welcome.html', 25, false, NOW(), '1.1 Collect & Store Data', false, 'Extracting tabular, document, and transactional records from operational databases into S3 using AWS Database Migration Service (AWS DMS) CDC replication.', 'Key Concept: Use AWS DMS with Change Data Capture (CDC) to continuously stream database row updates from Amazon RDS/DynamoDB into Amazon S3 for near real-time model retraining.'),
  ('mla-1-1-4', 'user-default', 'goal-aws', 'Streaming Data Ingestion (Amazon Kinesis Data Streams vs Amazon Data Firehose)', 'Domain 1: Data Preparation', 'Medium', 'https://docs.aws.amazon.com/streams/latest/dev/introduction.html', 30, false, NOW(), '1.1 Collect & Store Data', true, 'Architecting real-time event streaming for ML feature engineering using Kinesis Data Streams and automated S3 delivery via Data Firehose.', 'Exam Trap: If you need sub-second custom processing and strict order guarantee, choose Kinesis Data Streams. If you need simple, managed, zero-code batch ingestion into Amazon S3 or Amazon OpenSearch, choose Amazon Data Firehose (buffer 60s - 900s).'),
  ('mla-1-1-5', 'user-default', 'goal-aws', 'Streaming Analytics & Stream Processing (Apache Flink & Amazon MSK)', 'Domain 1: Data Preparation', 'Hard', 'https://docs.aws.amazon.com/kinesisanalytics/latest/java/what-is.html', 35, false, NOW(), '1.1 Collect & Store Data', false, 'Stateful stream processing using Amazon Managed Service for Apache Flink and Amazon Managed Streaming for Apache Kafka (MSK) for real-time feature extraction.', 'Key Concept: Apache Flink excels at tumbling and sliding time-window aggregations (e.g. average purchases over the last 15 minutes) before writing to SageMaker Feature Store.'),
  ('mla-1-1-6', 'user-default', 'goal-aws', 'Data Storage Formats (Apache Parquet, ORC, JSON, CSV) & Access Patterns', 'Domain 1: Data Preparation', 'Easy', 'https://docs.aws.amazon.com/athena/latest/ug/columnar-storage.html', 20, false, NOW(), '1.1 Collect & Store Data', true, 'Understand columnar vs row-based formats, compression algorithms (Snappy, GZIP), and their impact on query cost, I/O speed, and ML training throughput.', 'Exam Rule: Always convert CSV/JSON to columnar Apache Parquet with Snappy compression for analytical queries and SageMaker training inputs. Parquet reduces S3 query scan costs in Amazon Athena by up to 90%.')
INSERT INTO tasks (id, user_id, goal_id, title, topic, difficulty, url, duration, completed, created_at, subtopic, is_important, description, notes)
VALUES
  ('mla-1-1-7', 'user-default', 'goal-aws', 'Querying & Partitioning with Amazon Athena & AWS Glue Data Catalog', 'Domain 1: Data Preparation', 'Medium', 'https://docs.aws.amazon.com/athena/latest/ug/partitioning-data.html', 25, false, NOW(), '1.1 Collect & Store Data', false, 'Use Athena standard SQL to inspect S3 datasets, enforce partition projections (year/month/day), and catalog metadata using AWS Glue Crawlers.', 'Quick Tip: Proper S3 partition pruning (e.g., `s3://bucket/data/year=2026/month=11/`) prevents full table scans and drastically reduces Athena scan bytes and cost.'),
  ('mla-1-1-8', 'user-default', 'goal-aws', 'Scalable Vector Databases for AI (Amazon OpenSearch Service & OpenSearch Serverless)', 'Domain 1: Data Preparation', 'Hard', 'https://docs.aws.amazon.com/opensearch-service/latest/developerguide/knn.html', 40, false, NOW(), '1.1 Collect & Store Data', true, 'Configure vector indices using k-NN algorithms (HNSW and Inverted File - IVF) with cosine similarity and euclidean distance for enterprise RAG applications.', 'Exam Essential: Amazon OpenSearch Serverless Vector Engine is the standard fully-managed vector store for Amazon Bedrock Knowledge Bases. It supports high-scale similarity search with zero cluster management.'),
  ('mla-1-1-9', 'user-default', 'goal-aws', 'Relational Vector Stores (Amazon RDS & Aurora PostgreSQL with pgvector)', 'Domain 1: Data Preparation', 'Medium', 'https://docs.aws.amazon.com/AmazonRDS/latest/UserGuide/PostgreSQL.Concepts.General.FeatureSupport.Extensions.pgvector.html', 30, false, NOW(), '1.1 Collect & Store Data', true, 'Configuring the pgvector extension on Amazon Aurora / RDS PostgreSQL to store and index embeddings alongside traditional transactional relational data.', 'Decision Rule: Choose Aurora/RDS with `pgvector` when the organization already runs PostgreSQL and needs vector search without introducing or maintaining a separate search cluster.'),
  ('mla-1-1-10', 'user-default', 'goal-aws', 'Ingesting & Storing Diverse Multimodal Data (Audio, Video, Images, Text)', 'Domain 1: Data Preparation', 'Medium', 'https://docs.aws.amazon.com/kinesisvideostreams/latest/dg/what-is-kinesis-video.html', 25, false, NOW(), '1.1 Collect & Store Data', false, 'Handling binary raw assets in Amazon S3, video streaming through Amazon Kinesis Video Streams, and extracting frame-level annotations for model training.', 'Quick Note: For video ingestion pipelines targeting computer vision models, ingest streams via Kinesis Video Streams and process frames asynchronously with AWS Lambda and Amazon Rekognition.'),
  ('mla-1-1-11', 'user-default', 'goal-aws', 'SageMaker Feature Store: Online vs Offline Store Architecture', 'Domain 1: Data Preparation', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/feature-store.html', 35, false, NOW(), '1.1 Collect & Store Data', true, 'Design centralized feature repositories with low-latency Online Store (DynamoDB) and historical append-only Offline Store (S3) with Athena time-travel queries.', 'High-Yield Rule: The Online Store provides single-digit millisecond latency for real-time inference feature lookups. The Offline Store stores historical snapshots in S3 to prevent data leakage during model training.'),
  ('mla-1-2-1', 'user-default', 'goal-aws', 'Distributed Data Transformation (AWS Glue ETL & Apache Spark on Amazon EMR)', 'Domain 1: Data Preparation', 'Medium', 'https://docs.aws.amazon.com/glue/latest/dg/what-is-glue.html', 30, false, NOW(), '1.2 Transform & Feature Engineering', false, 'Execute large-scale batch feature transformations, joins, and schema normalization across terabytes of data using serverless AWS Glue ETL jobs.', 'Exam Tip: Use AWS Glue DynamicFrames when source datasets have inconsistent schemas or nested structures. For standard dataframes, convert to Spark DataFrames for native ML transformations.'),
  ('mla-1-2-2', 'user-default', 'goal-aws', 'Visual Data Preparation (AWS Glue DataBrew & SageMaker Data Wrangler)', 'Domain 1: Data Preparation', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/data-wrangler.html', 25, false, NOW(), '1.2 Transform & Feature Engineering', true, 'Interactive data exploration, cleaning, and transformation recipes. Export Data Wrangler flow directly into SageMaker Pipelines or Feature Store.', 'Quick Revision: SageMaker Data Wrangler allows ML engineers to visually prepare tabular and image data with 300+ transformations and export the processing flow directly as a SageMaker Pipeline step.'),
  ('mla-1-2-3', 'user-default', 'goal-aws', 'Real-Time Streaming Feature Transformations (AWS Lambda & Spark Streaming)', 'Domain 1: Data Preparation', 'Medium', 'https://docs.aws.amazon.com/lambda/latest/dg/with-kinesis.html', 25, false, NOW(), '1.2 Transform & Feature Engineering', false, 'Transform streaming event payloads on-the-fly using AWS Lambda event source mappings with Kinesis streams before persisting to feature stores.', 'Exam Trap: Ensure Lambda batch size and bisect-batch-on-function-error are configured to isolate poisonous records without stalling the entire Kinesis shard stream.'),
  ('mla-1-2-4', 'user-default', 'goal-aws', 'Classical Feature Engineering (Scaling, Standardization, Binning, Normalization)', 'Domain 1: Data Preparation', 'Easy', 'https://docs.aws.amazon.com/sagemaker/latest/dg/cdf-feature-engineering.html', 20, false, NOW(), '1.2 Transform & Feature Engineering', true, 'Mathematical feature transformations: Min-Max scaling, Z-score standardization, quantile binning, and polynomial features.', 'Exam Rule: Always compute feature scaling parameters (mean, standard deviation, min, max) on the TRAINING split only, then apply them to validation/test splits to prevent data leakage.'),
  ('mla-1-2-5', 'user-default', 'goal-aws', 'Categorical Encoding & Skewness Handling (One-Hot, Target Encoding, Log Transforms)', 'Domain 1: Data Preparation', 'Easy', 'https://docs.aws.amazon.com/sagemaker/latest/dg/cdf-categorical.html', 20, false, NOW(), '1.2 Transform & Feature Engineering', false, 'Handling high-cardinality categorical variables and correcting heavily right-skewed distributions with log or Box-Cox transformations.', 'Key Concept: Use log transform `log(x + 1)` on right-skewed positive data (e.g. monetary transactions, counts) to stabilize variance for linear models and neural networks.'),
  ('mla-1-2-6', 'user-default', 'goal-aws', 'Advanced Text Pre-Processing (Tokenization, BPE, WordPiece, Stemming)', 'Domain 1: Data Preparation', 'Medium', 'https://docs.aws.amazon.com/bedrock/latest/userguide/model-parameters.html', 25, false, NOW(), '1.2 Transform & Feature Engineering', true, 'Subword tokenization algorithms (Byte-Pair Encoding, WordPiece), vocabulary limits, special tokens ([CLS], [SEP], <eos>), and text cleaning.', 'Exam Note: Foundation models do not process raw words; text is tokenized into subwords. 1,000 tokens roughly equates to 750 English words.'),
  ('mla-1-2-7', 'user-default', 'goal-aws', 'Document Preparation & Chunking Strategies for RAG Applications', 'Domain 1: Data Preparation', 'Hard', 'https://docs.aws.amazon.com/bedrock/latest/userguide/knowledge-base-chunking.html', 35, false, NOW(), '1.2 Transform & Feature Engineering', true, 'Fixed-size, sliding window with overlap, semantic, and hierarchical parent-document chunking strategies for Amazon Bedrock Knowledge Bases.', 'Crucial Rule: Small chunks (200-300 tokens) yield high precision vector similarity search, while large chunks preserve context. Hierarchical chunking indexes small child chunks for search but retrieves the larger parent chunk for LLM prompt synthesis.'),
  ('mla-1-2-8', 'user-default', 'goal-aws', 'Vector Embeddings Generation (Amazon Titan Text Embeddings & Cohere Embed)', 'Domain 1: Data Preparation', 'Medium', 'https://docs.aws.amazon.com/bedrock/latest/userguide/titan-embedding-models.html', 25, false, NOW(), '1.2 Transform & Feature Engineering', true, 'Convert unstructured documents and search queries into dense vector representations using Amazon Titan Embeddings v2 and Cohere multilingual models.', 'Exam Trap: Always use the EXACT same embedding model for both document indexing and query inference; mismatched models produce incompatible vector spaces and zero retrieval accuracy.'),
  ('mla-1-2-9', 'user-default', 'goal-aws', 'Sensitive Data Masking, Anonymization & PII Redaction', 'Domain 1: Data Preparation', 'Medium', 'https://docs.aws.amazon.com/comprehend/latest/dg/pii.html', 25, false, NOW(), '1.2 Transform & Feature Engineering', true, 'Detecting and redacting PII (personally identifiable information) using Amazon Comprehend before data enters embedding pipelines or model training sets.', 'Security Rule: Comply with GDPR/HIPAA by applying Amazon Comprehend PII redaction (masking credit cards, SSNs, phone numbers) before data is stored in S3 training buckets or vector databases.'),
  ('mla-1-2-10', 'user-default', 'goal-aws', 'Data Formatting for FM Fine-Tuning & Model Distillation', 'Domain 1: Data Preparation', 'Hard', 'https://docs.aws.amazon.com/bedrock/latest/userguide/model-customization-prepare.html', 35, false, NOW(), '1.2 Transform & Feature Engineering', true, 'Structuring prompt-response pairs into JSON Lines (JSONL) datasets for Amazon Bedrock instruction fine-tuning and continuous pre-training.', 'Exam Format: Bedrock fine-tuning requires `.jsonl` format where each line contains: `{"prompt": "...", "completion": "..."}` with strict validation checks.'),
  ('mla-1-3-1', 'user-default', 'goal-aws', 'Automated Data Quality Validation (AWS Glue Data Quality & DQDL Rules)', 'Domain 1: Data Preparation', 'Medium', 'https://docs.aws.amazon.com/glue/latest/dg/glue-data-quality.html', 25, false, NOW(), '1.3 Data Quality & Bias', false, 'Automate data profiling and author Data Quality Definition Language (DQDL) rules to halt corrupted ETL pipelines before model training.', 'Rule Syntax: `Rules = [ Completeness "transaction_id" = 1.0, ColumnValues "age" between 18 and 100 ]`. Fails the Glue job if data violates business constraints.'),
  ('mla-1-3-2', 'user-default', 'goal-aws', 'Data Labeling & Annotation Workflows (SageMaker Ground Truth & Plus)', 'Domain 1: Data Preparation', 'Easy', 'https://docs.aws.amazon.com/sagemaker/latest/dg/sms.html', 25, false, NOW(), '1.3 Data Quality & Bias', true, 'Configure data labeling jobs with automated data labeling (active learning), private workforce, Amazon Mechanical Turk, and Ground Truth Plus.', 'Decision Rule: For sensitive or regulated data (medical, financial), ALWAYS choose a Private Workforce with Amazon Cognito or AWS IAM Identity Center. Never use Mechanical Turk for confidential PII.'),
  ('mla-1-3-3', 'user-default', 'goal-aws', 'Resolving Class Imbalance (SMOTE, Over/Under-Sampling, Class Weights)', 'Domain 1: Data Preparation', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/clarify-detect-data-bias.html', 25, false, NOW(), '1.3 Data Quality & Bias', true, 'Techniques for extreme class imbalance in fraud detection and rare event prediction: SMOTE interpolation, random undersampling, and weighted loss functions.', 'Exam Trap: In highly imbalanced datasets (e.g. 99% non-fraud, 1% fraud), Accuracy is a useless metric! Optimize for Precision, Recall, PR-AUC, or F1-Score instead.'),
  ('mla-1-3-4', 'user-default', 'goal-aws', 'Pre-Training Bias Detection with SageMaker Clarify (CI, DPL, Disparate Impact)', 'Domain 1: Data Preparation', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/clarify-bias-metrics.html', 35, false, NOW(), '1.3 Data Quality & Bias', true, 'Quantify bias before training begins: Class Imbalance (CI), Difference in Positive Proportions in Labels (DPL), and Disparate Impact.', 'Must-Know Metric: Disparate Impact evaluates the ratio of positive outcomes between unprivileged and privileged groups. A value < 0.8 is considered discriminatory adverse impact.'),
  ('mla-1-3-5', 'user-default', 'goal-aws', 'Multimodal Data Distribution & Bias across Numeric, Text, and Images', 'Domain 1: Data Preparation', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/clarify-bias-metrics.html', 25, false, NOW(), '1.3 Data Quality & Bias', false, 'Evaluate dataset representation and skew across multimodal assets (e.g., demographic distribution across image catalogues and text transcripts).', 'Key Concept: Ensure balanced representation across demographic subgroups in training imagery to prevent algorithmic performance degradation across minority facets.'),
  ('mla-1-3-6', 'user-default', 'goal-aws', 'AI Training Data Integrity & Content Safety Screening', 'Domain 1: Data Preparation', 'Medium', 'https://docs.aws.amazon.com/bedrock/latest/userguide/guardrails.html', 30, false, NOW(), '1.3 Data Quality & Bias', true, 'Screening instruction-tuning and pre-training corpora for toxic prompts, data poisoning, copyrighted material, and hallucinations.', 'Best Practice: Apply MinHash and Locality Sensitive Hashing (LSH) for near-deduplication of web crawls, and run automated safety filters on prompt-response pairs.'),
  ('mla-1-3-7', 'user-default', 'goal-aws', 'Data Cleaning (Outlier Detection with Z-Score/IQR, Imputation, Deduplication)', 'Domain 1: Data Preparation', 'Easy', 'https://docs.aws.amazon.com/sagemaker/latest/dg/cdf-data-cleaning.html', 20, false, NOW(), '1.3 Data Quality & Bias', false, 'Detecting anomalous data points using Interquartile Range (IQR) and Z-score thresholds; handling missing values with median, mode, or KNN imputation.', 'Rule of Thumb: For skewed features with heavy outliers, impute missing values using the Median instead of the Mean, as the mean is distorted by extreme values.'),
  ('mla-2-1-1', 'user-default', 'goal-aws', 'Amazon Bedrock Foundation Model Selection Matrix (Claude, Titan, Llama, Mistral)', 'Domain 2: FM & ML Modeling', 'Hard', 'https://docs.aws.amazon.com/bedrock/latest/userguide/models-supported.html', 35, false, NOW(), '2.1 Model & FM Selection', true, 'Compare capabilities, context window lengths, latency, and costs of Claude 3.5 Sonnet, Claude 3.5 Haiku, Amazon Titan, Meta Llama 3, and Mistral.', 'Exam Decision Matrix: For complex multi-step reasoning and coding, choose Claude 3.5 Sonnet. For fast, high-volume, low-cost classification, choose Claude 3.5 Haiku. For native AWS cost-efficiency, choose Amazon Titan.'),
  ('mla-2-1-2', 'user-default', 'goal-aws', 'Fine-Tuning Strategies for Pre-Trained FMs (PEFT / LoRA vs Full Fine-Tuning)', 'Domain 2: FM & ML Modeling', 'Hard', 'https://docs.aws.amazon.com/bedrock/latest/userguide/custom-models.html', 35, false, NOW(), '2.1 Model & FM Selection', true, 'Select between Prompt Engineering, RAG, PEFT / LoRA (Low-Rank Adaptation), and Full Fine-Tuning based on data volume, budget, and task specificity.', 'Exam Golden Rule: When knowledge is dynamic/frequently changing, ALWAYS choose RAG. When the model needs to learn domain-specific terminology or strict output format, choose Fine-Tuning via PEFT/LoRA.'),
  ('mla-2-1-3', 'user-default', 'goal-aws', 'Classical ML Algorithm Selection: Tabular & Regression (XGBoost, Linear Learner)', 'Domain 2: FM & ML Modeling', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/xgboost.html', 30, false, NOW(), '2.1 Model & FM Selection', true, 'Deep dive into Amazon SageMaker built-in XGBoost and Linear Learner algorithms for structured tabular regression and classification tasks.', 'Top Pick: XGBoost is the highest-performing built-in algorithm for structured tabular data. It handles non-linear relationships, missing values, and feature interactions out-of-the-box.')
INSERT INTO tasks (id, user_id, goal_id, title, topic, difficulty, url, duration, completed, created_at, subtopic, is_important, description, notes)
VALUES
  ('mla-2-1-4', 'user-default', 'goal-aws', 'Classical ML Algorithm Selection: Time-Series & Anomaly Detection (DeepAR, RCF)', 'Domain 2: FM & ML Modeling', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/deepar.html', 30, false, NOW(), '2.1 Model & FM Selection', true, 'Choose Random Cut Forest (RCF) for unsupervised tabular/streaming anomaly detection and DeepAR for probabilistic multi-series time-series forecasting.', 'Exam Trigger Words: ''Probabilistic forecast across thousands of related products'' -> DeepAR. ''Real-time anomaly detection in streaming IoT logs without labeled data'' -> Random Cut Forest (RCF).'),
  ('mla-2-1-5', 'user-default', 'goal-aws', 'Classical ML Algorithm Selection: NLP & Embeddings (BlazingText, Object2Vec)', 'Domain 2: FM & ML Modeling', 'Easy', 'https://docs.aws.amazon.com/sagemaker/latest/dg/blazingtext.html', 25, false, NOW(), '2.1 Model & FM Selection', false, 'SageMaker BlazingText for high-speed Word2Vec / text classification on GPUs and Object2Vec for paired entity embeddings (user-product recommendations).', 'Key Difference: BlazingText provides fast GPU-accelerated text classification and word embedding generation. Object2Vec maps pairs of objects into embedding vectors for recommendation systems.'),
  ('mla-2-1-6', 'user-default', 'goal-aws', 'Build vs Buy Tradeoffs (Custom SageMaker vs Managed AI vs Bedrock FMs)', 'Domain 2: FM & ML Modeling', 'Easy', 'https://docs.aws.amazon.com/whitepapers/latest/aws-overview/machine-learning.html', 20, false, NOW(), '2.1 Model & FM Selection', true, 'Evaluate tradeoffs between managed AWS AI services (zero ML expertise needed), serverless Amazon Bedrock FMs, and custom SageMaker model development.', 'Exam Principle: If a pre-trained managed AI service (Textract, Rekognition, Comprehend) satisfies the business requirement, ALWAYS choose it over building a custom model on SageMaker to minimize development cost.'),
  ('mla-2-1-7', 'user-default', 'goal-aws', 'Advanced RAG Architecture Patterns (Query Rewriting, HyDE, Multi-Query)', 'Domain 2: FM & ML Modeling', 'Hard', 'https://docs.aws.amazon.com/bedrock/latest/userguide/knowledge-base.html', 35, false, NOW(), '2.1 Model & FM Selection', true, 'Advanced RAG retrieval patterns: Hypothetical Document Embeddings (HyDE), query rewriting, multi-query expansion, and parent-document retrieval.', 'HyDE Technique: Generates a hypothetical answer with an LLM first, embeds that answer, and searches the vector store using the answer embedding rather than the brief user question.'),
  ('mla-2-1-8', 'user-default', 'goal-aws', 'Hybrid Search Architectures (Combining BM25 Lexical + Vector Semantic Search)', 'Domain 2: FM & ML Modeling', 'Hard', 'https://docs.aws.amazon.com/opensearch-service/latest/developerguide/hybrid-search.html', 30, false, NOW(), '2.1 Model & FM Selection', true, 'Configuring OpenSearch hybrid search queries to combine traditional BM25 keyword matching with dense neural vector search using Reciprocal Rank Fusion (RRF).', 'Exam Scenario: When search queries contain exact product codes, SKUs, or specialized acronyms alongside semantic questions, hybrid search (keyword + vector) delivers higher recall than vector search alone.'),
  ('mla-2-1-9', 'user-default', 'goal-aws', 'Pre-Trained AWS AI Services (Textract, Rekognition, Comprehend, Transcribe)', 'Domain 2: FM & ML Modeling', 'Easy', 'https://docs.aws.amazon.com/textract/latest/dg/what-is.html', 25, false, NOW(), '2.1 Model & FM Selection', false, 'Targeted business use cases for Amazon Textract (document OCR), Rekognition (computer vision), Comprehend (NLP/sentiment), and Transcribe (audio to text).', 'Matching Cheat Sheet: Scanned invoices/receipts with tables -> Textract. Sentiment/Key phrases in customer calls -> Transcribe + Comprehend. Video facial analysis -> Rekognition.'),
  ('mla-2-1-10', 'user-default', 'goal-aws', 'Tradeoff Analysis: Accuracy vs Latency vs Cost vs Quantization (INT8, FP16)', 'Domain 2: FM & ML Modeling', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/neo.html', 25, false, NOW(), '2.1 Model & FM Selection', true, 'Model compression and post-training quantization techniques to reduce memory footprint and latency while maintaining accuracy.', 'Quantization Note: Quantizing 16-bit floating-point weights (FP16) down to 8-bit integers (INT8) cuts GPU memory usage in half and accelerates inference throughput with negligible drop in perplexity.'),
  ('mla-2-2-1', 'user-default', 'goal-aws', 'SageMaker Script Mode with PyTorch, TensorFlow & Hugging Face', 'Domain 2: FM & ML Modeling', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/adapt-training-container.html', 30, false, NOW(), '2.2 Training & Customization', true, 'Configuring SageMaker PyTorch and HuggingFace Estimators using `entry_point=''train.py''` and `source_dir`, passing S3 channels via environment variables.', 'Script Mode Pattern: SageMaker injects training data paths into environment variable `SM_CHANNEL_TRAIN` and expects model artifacts to be saved in directory `SM_MODEL_DIR` for automatic S3 packaging.'),
  ('mla-2-2-2', 'user-default', 'goal-aws', 'Automatic Model Tuning (AMT) & Hyperparameter Optimization', 'Domain 2: FM & ML Modeling', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/automatic-model-tuning.html', 30, false, NOW(), '2.2 Training & Customization', true, 'Configure SageMaker HyperparameterTuner with Bayesian search, define objective metrics via regex log parsing, and enable early stopping with Hyperband.', 'Tuning Strategy: Bayesian Optimization treats hyperparameter selection as a regression problem to explore the search space efficiently. Warm Start enables incremental tuning runs based on prior completed trials.'),
  ('mla-2-2-3', 'user-default', 'goal-aws', 'Distributed Data Parallel Training (SageMaker Data Parallelism - SMDDP)', 'Domain 2: FM & ML Modeling', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/data-parallel.html', 35, false, NOW(), '2.2 Training & Customization', true, 'Scale model training across multi-node GPU clusters (p4d/g5) by sharding dataset batches across nodes with synchronized gradient averaging.', 'Decision Rule: Use Data Parallelism when the entire model easily fits inside a single GPU''s memory, but the dataset is massive and training time needs linear speedup.'),
  ('mla-2-2-4', 'user-default', 'goal-aws', 'Distributed Model Parallel Training for Large LLMs (SageMaker Model Parallelism - SMP)', 'Domain 2: FM & ML Modeling', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/model-parallel.html', 35, false, NOW(), '2.2 Training & Customization', true, 'Pipeline parallelism and tensor parallelism techniques to partition multi-billion parameter foundation models across multiple GPU VRAM cards.', 'Decision Rule: Use Model Parallelism (SMP) when the model weights and activations exceed the VRAM of a single GPU (e.g. 70B+ parameter LLMs).'),
  ('mla-2-2-5', 'user-default', 'goal-aws', 'Preventing Overfitting, Underfitting & Catastrophic Forgetting', 'Domain 2: FM & ML Modeling', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/cdf-model-tuning.html', 25, false, NOW(), '2.2 Training & Customization', false, 'Regularization (L1 Lasso, L2 Ridge, Dropout), Early Stopping callbacks, and replay buffer rehearsal datasets to prevent catastrophic forgetting in fine-tuned LLMs.', 'Catastrophic Forgetting: When an FM is fine-tuned on a narrow new task, it may lose its general conversational abilities. Mitigate using Parameter-Efficient Fine-Tuning (LoRA) or mixing 10-20% general dataset replay.'),
  ('mla-2-2-6', 'user-default', 'goal-aws', 'Ensembling Methods (Bagging, Boosting, Stacking, Voting Classifiers)', 'Domain 2: FM & ML Modeling', 'Easy', 'https://docs.aws.amazon.com/sagemaker/latest/dg/xgboost.html', 20, false, NOW(), '2.2 Training & Customization', false, 'Combine predictions from multiple independent ML models to reduce bias (boosting) or variance (bagging) and improve out-of-sample generalization.', 'Comparison: Bagging (Random Forest) trains models in parallel to reduce variance. Boosting (XGBoost) trains models sequentially to reduce bias by focusing on prior mistakes.'),
  ('mla-2-2-7', 'user-default', 'goal-aws', 'Fundamental Hyperparameter Tuning (Learning Rate Schedules, Warmup, Batch Size)', 'Domain 2: FM & ML Modeling', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/automatic-model-tuning-considerations.html', 25, false, NOW(), '2.2 Training & Customization', false, 'Impact of learning rate schedules (cosine annealing, linear warmup), mini-batch size, weight decay, and gradient clipping on model convergence.', 'Exam Trap: If training loss explodes or oscillates wildly, the Learning Rate is too high. If loss decreases imperceptibly slowly, the Learning Rate is too small.'),
  ('mla-2-2-8', 'user-default', 'goal-aws', 'Advanced Prompt Engineering (Few-Shot, Chain-of-Thought, ReAct Framework)', 'Domain 2: FM & ML Modeling', 'Medium', 'https://docs.aws.amazon.com/bedrock/latest/userguide/prompt-engineering-guidelines.html', 30, false, NOW(), '2.2 Training & Customization', true, 'Design structured system prompts, Few-Shot exemplars, Chain-of-Thought (CoT) step-by-step reasoning, and ReAct loop orchestrations for Bedrock models.', 'Prompt Tip: Chain-of-Thought prompting (''Think step-by-step before answering'') dramatically improves multi-step math and logical deduction accuracy in foundation models.'),
  ('mla-2-2-9', 'user-default', 'goal-aws', 'Embedding Model Fine-Tuning & Chunk Sizing Optimization', 'Domain 2: FM & ML Modeling', 'Hard', 'https://docs.aws.amazon.com/bedrock/latest/userguide/titan-embedding-models.html', 35, false, NOW(), '2.2 Training & Customization', false, 'Fine-tune text embeddings on proprietary technical jargon and benchmark retrieval recall across varying chunk sizes and overlap percentages.', 'Tuning Rule: When domain queries use specialized abbreviations and acronyms not present in public web datasets, fine-tune the embedding model to cluster domain synonyms together.'),
  ('mla-2-3-1', 'user-default', 'goal-aws', 'Experiment Tracking & Lineage with MLflow on SageMaker AI & SageMaker Experiments', 'Domain 2: FM & ML Modeling', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/experiments.html', 30, false, NOW(), '2.3 Evaluation & Validation', true, 'Track parameters, code versions, metrics, and dataset hashes using fully-managed MLflow on SageMaker AI for auditability and experiment reproducibility.', 'Best Practice: Managed MLflow on SageMaker AI enables teams to visualize metric curves across training runs and maintain end-to-end data/model artifact lineage.'),
  ('mla-2-3-2', 'user-default', 'goal-aws', 'Classical ML Evaluation Metrics (Precision, Recall, F1, ROC-AUC, PR-AUC, RMSE)', 'Domain 2: FM & ML Modeling', 'Easy', 'https://docs.aws.amazon.com/sagemaker/latest/dg/cdf-model-evaluation.html', 25, false, NOW(), '2.3 Evaluation & Validation', true, 'Select appropriate evaluation metrics based on business objectives: False Positives (Precision) vs False Negatives (Recall) trade-off.', 'Exam Trap: Medical cancer detection or fraud alerting -> High Recall (minimize false negatives). Spam filter -> High Precision (minimize false positives). Imbalanced binary classification -> PR-AUC over ROC-AUC.'),
  ('mla-2-3-3', 'user-default', 'goal-aws', 'NLP & Generation Evaluation Metrics (BLEU, ROUGE-1/2/L, BERTScore, Perplexity)', 'Domain 2: FM & ML Modeling', 'Medium', 'https://docs.aws.amazon.com/bedrock/latest/userguide/model-evaluation.html', 30, false, NOW(), '2.3 Evaluation & Validation', true, 'Evaluating natural language generation: n-gram precision (BLEU), n-gram recall (ROUGE), and contextual semantic embedding similarity (BERTScore).', 'Cheat Sheet: Machine Translation -> BLEU. Text Summarization -> ROUGE-1, ROUGE-2, and ROUGE-L. Semantic Paraphrase Quality -> BERTScore.'),
  ('mla-2-3-4', 'user-default', 'goal-aws', 'Amazon Bedrock Automated Model Evaluation & LLM-as-a-Judge Frameworks', 'Domain 2: FM & ML Modeling', 'Hard', 'https://docs.aws.amazon.com/bedrock/latest/userguide/model-evaluation.html', 35, false, NOW(), '2.3 Evaluation & Validation', true, 'Configure Bedrock Model Evaluation jobs using automated benchmarks or LLM-as-a-judge to evaluate accuracy, toxicity, and hallucinations across prompt datasets.', 'High-Yield Feature: Amazon Bedrock Model Evaluation enables automated side-by-side comparison of candidate models on custom prompt datasets scored by an authoritative judge LLM.'),
  ('mla-2-3-5', 'user-default', 'goal-aws', 'Human-in-the-Loop Evaluation (Amazon Augmented AI - A2I & Ground Truth)', 'Domain 2: FM & ML Modeling', 'Medium', 'https://docs.aws.amazon.com/augmented-ai/latest/devguide/what-is-a2i.html', 25, false, NOW(), '2.3 Evaluation & Validation', false, 'Route low-confidence model predictions or sensitive GenAI outputs to human reviewers using Amazon Augmented AI (Amazon A2I) review loops.', 'Architecture Rule: When a model''s prediction confidence score falls below a safety threshold (e.g., < 0.85), Amazon A2I triggers a human review task automatically.'),
  ('mla-2-3-6', 'user-default', 'goal-aws', 'Explainability with SageMaker Clarify (SHAP Values & Feature Attribution)', 'Domain 2: FM & ML Modeling', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/clarify-feature-attribute-shap-values.html', 35, false, NOW(), '2.3 Evaluation & Validation', true, 'Compute Shapley Additive Explanations (SHAP) post-training to generate global feature importance summaries and individual local prediction explanations.', 'Compliance Requirement: Regulated decisions (credit card denials, insurance underwriting) require local SHAP explanations to produce legally compliant Adverse Action notices explaining why an individual was rejected.'),
  ('mla-2-3-7', 'user-default', 'goal-aws', 'Debugging Model Convergence Issues with SageMaker Debugger', 'Domain 2: FM & ML Modeling', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/train-debugger.html', 25, false, NOW(), '2.3 Evaluation & Validation', false, 'Monitor real-time training tensors, detect vanishing/exploding gradients, identify non-improving loss curves, and profile GPU utilization bottlenecks.', 'Troubleshooting: SageMaker Debugger built-in rules (e.g. `VanishingGradient`, `Overfitting`, `LossNotDecreasing`) can automatically terminate failing training jobs to save compute costs.'),
  ('mla-2-3-8', 'user-default', 'goal-aws', 'RAG Evaluation Metrics (Context Relevance, Groundedness/Faithfulness, Answer Relevance)', 'Domain 2: FM & ML Modeling', 'Hard', 'https://docs.aws.amazon.com/bedrock/latest/userguide/knowledge-base.html', 35, false, NOW(), '2.3 Evaluation & Validation', true, 'Assessing RAG performance using the RAG Triad: Context Relevance (retrieval quality), Groundedness (hallucination check), and Answer Relevance (query satisfaction).', 'Core RAG Metrics: If Context Relevance is low -> tune chunk size or vector index. If Groundedness is low -> prompt engineering to strictly constrain response to context.'),
  ('mla-3-1-1', 'user-default', 'goal-aws', 'SageMaker Inference Options: Real-Time vs Serverless vs Asynchronous vs Batch Transform', 'Domain 3: MLOps & Deployment', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/deploy-model.html', 40, false, NOW(), '3.1 Deployment Infrastructure', true, 'Exhaustive comparison of SageMaker inference hosting options based on latency, payload limits, invocation patterns, and cost behavior.', 'CRITICAL EXAM DECISION MATRIX: Real-Time (sub-100ms, persistent instances, 6MB payload). Serverless (infrequent/spiky, scales to 0, 4MB payload). Asynchronous (up to 1GB payload, up to 1hr execution, S3+SQS queue). Batch Transform (offline dataset scoring, TBs of data).')
INSERT INTO tasks (id, user_id, goal_id, title, topic, difficulty, url, duration, completed, created_at, subtopic, is_important, description, notes)
VALUES
  ('mla-3-1-2', 'user-default', 'goal-aws', 'Multi-Model Endpoints (MME) for Cost-Effective Hosting of 100s of Models', 'Domain 3: MLOps & Deployment', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/multi-model-endpoints.html', 35, false, NOW(), '3.1 Deployment Infrastructure', true, 'Deploy hundreds of homogeneous models on a shared instance pool behind a single endpoint, dynamically loading models into memory from S3 upon invocation.', 'Cost Saver Rule: When you have 50-1000 similar models with infrequent individual traffic (e.g. per-customer models), ALWAYS choose SageMaker Multi-Model Endpoints (MME) to avoid paying for dedicated instances per model.'),
  ('mla-3-1-3', 'user-default', 'goal-aws', 'Multi-Container Endpoints (MCE) & Serial Inference Pipelines', 'Domain 3: MLOps & Deployment', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/multi-container-endpoints.html', 30, false, NOW(), '3.1 Deployment Infrastructure', false, 'Chain pre-processing, inference, and post-processing containers together in a sequential pipeline behind a single HTTPS endpoint.', 'Inference Pipeline Pattern: Container 1 (Scikit-Learn feature transformer) -> Container 2 (XGBoost / PyTorch model) -> Container 3 (Post-processing response formatter). Avoids extra S3 round-trips.'),
  ('mla-3-1-4', 'user-default', 'goal-aws', 'Foundation Model Deployment Options: Bedrock On-Demand vs Provisioned Throughput vs JumpStart', 'Domain 3: MLOps & Deployment', 'Hard', 'https://docs.aws.amazon.com/bedrock/latest/userguide/prov-throughput.html', 35, false, NOW(), '3.1 Deployment Infrastructure', true, 'Tradeoffs between serverless token billing (On-Demand), dedicated Model Units with commitment (Provisioned Throughput), and dedicated SageMaker hosting.', 'Exam Decision: For variable or development traffic, use Bedrock On-Demand. For large production workloads requiring guaranteed throughput without rate-limiting (throttling), purchase Bedrock Provisioned Throughput.'),
  ('mla-3-1-5', 'user-default', 'goal-aws', 'Deploying External Models (SageMaker BYOM & Amazon Bedrock Custom Model Import)', 'Domain 3: MLOps & Deployment', 'Medium', 'https://docs.aws.amazon.com/bedrock/latest/userguide/model-customization-import-model.html', 30, false, NOW(), '3.1 Deployment Infrastructure', true, 'Import externally trained weights (from Hugging Face or on-premises) into Amazon Bedrock via Custom Model Import or host custom containers in SageMaker.', 'New Feature in MLA-C02: Amazon Bedrock Custom Model Import allows you to import custom fine-tuned model architectures (Llama, Mistral) into Bedrock and invoke them through standard serverless Bedrock APIs.'),
  ('mla-3-1-6', 'user-default', 'goal-aws', 'Amazon Bedrock Agents: Action Groups, OpenAPI Schemas & Lambda Integrations', 'Domain 3: MLOps & Deployment', 'Hard', 'https://docs.aws.amazon.com/bedrock/latest/userguide/agents.html', 40, false, NOW(), '3.1 Deployment Infrastructure', true, 'Build autonomous multi-step agents in Bedrock: define action groups with OpenAPI 3.0 schemas, connect Lambda functions, and orchestrate with user instructions.', 'Agent Core Architecture: The LLM breaks down complex queries into steps, inspects the OpenAPI schema of connected Action Groups, decides which tool/API to invoke, executes via AWS Lambda, and synthesizes the response.'),
  ('mla-3-1-7', 'user-default', 'goal-aws', 'Bedrock Knowledge Bases Deployment & Reranking (Cohere Rerank)', 'Domain 3: MLOps & Deployment', 'Hard', 'https://docs.aws.amazon.com/bedrock/latest/userguide/knowledge-base.html', 35, false, NOW(), '3.1 Deployment Infrastructure', true, 'Deploy managed RAG with Bedrock Knowledge Bases, connect to OpenSearch Serverless, and configure advanced rerank models (Cohere Rerank) to filter retrieved chunks.', 'Reranking Advantage: Vector search retrieves top 20 candidate chunks based on vector distance; Cohere Rerank cross-encodes the query and candidates to score true semantic relevance, passing only top 5 to the generator LLM.'),
  ('mla-3-2-1', 'user-default', 'goal-aws', 'Compute Instance Selection: CPU (c6i/c7g) vs GPU (g5/p4de) vs Silicon (Inf2/Trn1)', 'Domain 3: MLOps & Deployment', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/instance-types.html', 30, false, NOW(), '3.2 Resource Provisioning', true, 'Select optimal EC2 instance families for ML training and inference: Graviton ARM, NVIDIA Tensor Core GPUs, AWS Inferentia (Inf2), and AWS Trainium (Trn1).', 'Silicon Rules: Choose AWS Trainium (trn1) for lowest cost-to-train deep learning and LLMs. Choose AWS Inferentia (inf2) for lowest latency and cost-per-inference on deep learning models.'),
  ('mla-3-2-2', 'user-default', 'goal-aws', 'VPC Network Environments & SageMaker PrivateLink (VPC Endpoints & S3 Gateway)', 'Domain 3: MLOps & Deployment', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/interface-vpc-endpoint.html', 40, false, NOW(), '3.2 Resource Provisioning', true, 'Architect secure private network topology: private subnets with no internet gateway, VPC Interface Endpoints for SageMaker API & Runtime, and S3 Gateway Endpoint.', 'CRITICAL SECURITY SCENARIO: For maximum security, launch training and endpoint clusters inside private subnets without NAT gateways. Access S3 via Gateway VPC Endpoint and SageMaker via Interface VPC Endpoints (PrivateLink).'),
  ('mla-3-2-3', 'user-default', 'goal-aws', 'Deploying & Hosting Models Programmatically (SageMaker Python SDK & Boto3)', 'Domain 3: MLOps & Deployment', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/realtime-endpoints-deployment.html', 25, false, NOW(), '3.2 Resource Provisioning', false, 'Programmatic resource provisioning lifecycle: `CreateModel` -> `CreateEndpointConfig` (production variants and instance types) -> `CreateEndpoint`.', 'SDK Sequence: In Boto3, you must create a Model resource and an EndpointConfig resource before you can create the live Endpoint.'),
  ('mla-3-2-4', 'user-default', 'goal-aws', 'Auto-Scaling Policies for SageMaker Endpoints (Target Tracking & Scaling Metrics)', 'Domain 3: MLOps & Deployment', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/endpoint-auto-scaling.html', 30, false, NOW(), '3.2 Resource Provisioning', true, 'Configure Application Auto Scaling on SageMaker production variants using Target Tracking on `SageMakerVariantInvocationsPerInstance` metric.', 'Exam Favorite: The recommended metric for auto-scaling SageMaker real-time endpoints is `SageMakerVariantInvocationsPerInstance`. Configure cooldown periods to prevent rapid flapping.'),
  ('mla-3-2-5', 'user-default', 'goal-aws', 'Building & Maintaining Deep Learning Containers (AWS DLCs & Amazon ECR)', 'Domain 3: MLOps & Deployment', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/pre-built-containers-frameworks-deep-learning.html', 30, false, NOW(), '3.2 Resource Provisioning', false, 'Using pre-built AWS Deep Learning Containers (DLCs) for PyTorch and TensorFlow, custom Dockerfiles, and scanning container images in Amazon ECR.', 'Best Practice: Always start with official AWS Deep Learning Containers (DLCs) rather than building from scratch. DLCs are pre-optimized with CUDA and network acceleration.'),
  ('mla-3-2-6', 'user-default', 'goal-aws', 'Agent State Management Systems & Multi-Turn Conversation Memory (Amazon DynamoDB)', 'Domain 3: MLOps & Deployment', 'Hard', 'https://docs.aws.amazon.com/bedrock/latest/userguide/agents-session-state.html', 30, false, NOW(), '3.2 Resource Provisioning', true, 'Implement persistent conversational state and execution memory across agent sessions using Amazon DynamoDB and Bedrock Agent session attributes.', 'Architecture Pattern: Store user session IDs and serialized message histories in Amazon DynamoDB. Pass the session ID to Bedrock `InvokeAgent` to maintain context across multi-turn interactions.'),
  ('mla-3-2-7', 'user-default', 'goal-aws', 'AI-Specific Scaling for GPU Workloads (GPU Memory Utilization Tracking)', 'Domain 3: MLOps & Deployment', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/monitoring-cloudwatch.html', 25, false, NOW(), '3.2 Resource Provisioning', false, 'Install and configure CloudWatch agent on GPU compute instances to publish custom metrics: GPU memory used, GPU utilization, and PCIe throughput.', 'CloudWatch Detail: Standard CloudWatch EC2 metrics do NOT include GPU memory or GPU temperature. You must install the CloudWatch agent with NVIDIA Management Library (NVML) metrics enabled.'),
  ('mla-3-3-1', 'user-default', 'goal-aws', 'SageMaker Pipelines DAG Orchestration (Processing, Training, Tuning, Condition Steps)', 'Domain 3: MLOps & Deployment', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/pipelines-sdk.html', 40, false, NOW(), '3.3 MLOps & CI/CD', true, 'Build serverless ML workflows using SageMaker Pipelines Python SDK: define Directed Acyclic Graphs (DAGs) with dependencies, parameters, and conditional branching.', 'Pipeline Architecture: `ProcessingStep` (Data cleaning) -> `TrainingStep` (Model training) -> `ConditionStep` (Evaluate metric threshold, e.g. accuracy > 0.85) -> `RegisterModelStep` (Push to Model Registry).'),
  ('mla-3-3-2', 'user-default', 'goal-aws', 'Automated Model Retraining Triggers (Amazon EventBridge, S3 Events & CloudWatch)', 'Domain 3: MLOps & Deployment', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/automating-sagemaker-with-eventbridge.html', 30, false, NOW(), '3.3 MLOps & CI/CD', true, 'Event-driven MLOps: trigger SageMaker Pipelines automatically via Amazon EventBridge rules when new training data arrives in S3 or Model Monitor triggers a drift alarm.', 'Event-Driven MLOps: When S3 receives a new data drop or Model Monitor fires an alarm, CloudWatch raises an alert -> Amazon EventBridge rule matches the pattern -> Triggers `StartPipelineExecution`.'),
  ('mla-3-3-3', 'user-default', 'goal-aws', 'Safe Deployment Strategies: Blue/Green, Canary & Linear Traffic Shifting', 'Domain 3: MLOps & Deployment', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/deployment-guardrails.html', 35, false, NOW(), '3.3 MLOps & CI/CD', true, 'Deploy models with SageMaker Deployment Guardrails: Canary traffic shifting (e.g. 10% for 15 min), linear shifting, and automatic CloudWatch alarm rollback.', 'Deployment Guardrails: Configure `AutoRollbackConfiguration` tied to CloudWatch 5xx error alarms. If the new Canary variant throws errors during the bake period, SageMaker rolls back automatically with zero downtime.'),
  ('mla-3-3-4', 'user-default', 'goal-aws', 'SageMaker Shadow Testing: Comparing Candidate vs Production Models Safely', 'Domain 3: MLOps & Deployment', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/shadow-tests.html', 35, false, NOW(), '3.3 MLOps & CI/CD', true, 'Deploy a shadow variant alongside a production variant; 100% of live traffic is duplicated to the shadow model, but only production responses are returned to users.', 'TOP EXAM FAVORITE: When asked ''How to evaluate a new model''s latency and error rate under true production load without risking user experience?'', ALWAYS choose SageMaker Shadow Testing.'),
  ('mla-3-3-5', 'user-default', 'goal-aws', 'SageMaker Model Registry: Versioning, Approval Workflows & Governance', 'Domain 3: MLOps & Deployment', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/model-registry.html', 30, false, NOW(), '3.3 MLOps & CI/CD', true, 'Catalog model package groups, track model metrics, audit approvals (`PendingManualApproval`, `Approved`, `Rejected`), and automate downstream deployment.', 'Governance Pattern: New models register with `PendingManualApproval`. When a lead engineer approves the model in Model Registry, EventBridge triggers the AWS CodePipeline deployment to production.'),
  ('mla-3-3-6', 'user-default', 'goal-aws', 'AWS CI/CD Services for MLOps (CodeBuild, CodeDeploy, CodePipeline, CodeConnections)', 'Domain 3: MLOps & Deployment', 'Medium', 'https://docs.aws.amazon.com/codepipeline/latest/userguide/welcome.html', 30, false, NOW(), '3.3 MLOps & CI/CD', false, 'Integrate Git repositories (GitHub/CodeCommit) with AWS CodePipeline, run automated unit/integration tests in CodeBuild, and deploy infrastructure via CloudFormation.', 'CI/CD Pipeline: Source (CodeConnections/GitHub) -> Build (CodeBuild runs PyTest and linting) -> Deploy (CodePipeline invokes SageMaker Pipeline / CloudFormation template).'),
  ('mla-3-3-7', 'user-default', 'goal-aws', 'Amazon Bedrock Prompt Management & Versioning (Prompt Templates & Variables)', 'Domain 3: MLOps & Deployment', 'Medium', 'https://docs.aws.amazon.com/bedrock/latest/userguide/prompt-management.html', 25, false, NOW(), '3.3 MLOps & CI/CD', true, 'Manage, version, test, and save prompt templates with dynamic variables and inference parameter configurations in Amazon Bedrock Prompt Management.', 'New in MLA-C02: Bedrock Prompt Management lets teams create production aliases (e.g. `PROD` pointing to Version 3) so application code does not need redeployment when prompts are updated.'),
  ('mla-3-3-8', 'user-default', 'goal-aws', 'Automated Knowledge Base Ingestion & Refresh Pipelines (Bedrock StartIngestionJob)', 'Domain 3: MLOps & Deployment', 'Medium', 'https://docs.aws.amazon.com/bedrock/latest/userguide/knowledge-base-ingest.html', 30, false, NOW(), '3.3 MLOps & CI/CD', false, 'Automate synchronization between S3 document updates and OpenSearch vector indices using the Amazon Bedrock `StartIngestionJob` API.', 'Automation Tip: Trigger a Lambda function on S3 object creation (`s3:ObjectCreated:*`) that calls Bedrock''s `StartIngestionJob` to sync new documents into the vector index automatically.'),
  ('mla-4-1-1', 'user-default', 'goal-aws', 'SageMaker Model Monitor: Data Quality Monitoring (Baselines & Constraints)', 'Domain 4: Operations & Security', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/model-monitor-data-quality.html', 35, false, NOW(), '4.1 Monitoring & Observability', true, 'Establish baseline constraints and statistics during training, capture production payload requests, and detect statistical schema violations and data drift.', 'Data Quality Baseline: SageMaker Model Monitor outputs `constraints.json` and `statistics.json` on training data. During inference, it flags `constraint_violations.json` if input data distributions deviate.'),
  ('mla-4-1-2', 'user-default', 'goal-aws', 'SageMaker Model Monitor: Model Quality Monitoring (Ground Truth Label Matching)', 'Domain 4: Operations & Security', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/model-monitor-model-quality.html', 35, false, NOW(), '4.1 Monitoring & Observability', true, 'Monitor real-time degradation in model accuracy, precision, and recall by joining endpoint inference logs with delayed ground truth labels uploaded to S3.', 'Model Quality Flow: Ground truth labels (e.g. loan defaults observed 6 months later) are uploaded to S3. Model Monitor joins predictions with actual labels to detect accuracy and F1 degradation.'),
  ('mla-4-1-3', 'user-default', 'goal-aws', 'SageMaker Clarify Model Monitor: Bias Drift & Feature Attribution Drift', 'Domain 4: Operations & Security', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/clarify-model-monitor-bias-drift.html', 35, false, NOW(), '4.1 Monitoring & Observability', true, 'Continuous monitoring for algorithmic bias drift (Disparate Impact, DPL) and shifts in SHAP feature attribution rankings on live production endpoints.', 'Attribution Drift: When the relative importance of features shifts over time (e.g. interest rate becomes more predictive than credit score), Clarify flags Feature Attribution Drift.'),
  ('mla-4-1-4', 'user-default', 'goal-aws', 'Amazon CloudWatch Generative AI Observability (Invocations, Latency, Token Metrics)', 'Domain 4: Operations & Security', 'Medium', 'https://docs.aws.amazon.com/bedrock/latest/userguide/monitoring-cloudwatch.html', 30, false, NOW(), '4.1 Monitoring & Observability', true, 'Track Bedrock model metrics: `Invocations`, `InvocationClientErrors`, `InvocationServerErrors`, `ModelLatency`, `InputTokenCount`, and `OutputTokenCount`.', 'Key CloudWatch Metrics: Monitor `ModelLatency` (time spent in foundation model inference) vs `OverheadLatency` (network/SDK serialization time) to isolate performance bottlenecks.')
INSERT INTO tasks (id, user_id, goal_id, title, topic, difficulty, url, duration, completed, created_at, subtopic, is_important, description, notes)
VALUES
  ('mla-4-1-5', 'user-default', 'goal-aws', 'Agentic Workflow Observability: Coordination Failures, Truncated Streaming & Tool Retries', 'Domain 4: Operations & Security', 'Hard', 'https://docs.aws.amazon.com/bedrock/latest/userguide/agents.html', 35, false, NOW(), '4.1 Monitoring & Observability', true, 'Detecting and alerting on agent failure modes: tool execution timeouts, circular reasoning loops, truncated streaming responses, and AWS X-Ray trace analysis.', 'New in MLA-C02: Use AWS X-Ray integrated with Bedrock Agents to trace execution across each tool call and identify which Lambda action group timed out or caused an exception.'),
  ('mla-4-1-6', 'user-default', 'goal-aws', 'Production A/B Testing & Production Variants Configuration', 'Domain 4: Operations & Security', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/model-ab-testing.html', 25, false, NOW(), '4.1 Monitoring & Observability', false, 'Distribute live inference traffic between two model variants (e.g., 50% Variant A, 50% Variant B) on a single SageMaker endpoint to evaluate performance.', 'Configuration: In EndpointConfig, specify multiple `ProductionVariant` blocks with `InitialVariantWeight` (e.g. 0.5 and 0.5) to run live A/B testing across models.'),
  ('mla-4-2-1', 'user-default', 'goal-aws', 'SageMaker Managed Spot Training with Checkpointing (Up to 90% Savings)', 'Domain 4: Operations & Security', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/model-managed-spot-training.html', 30, false, NOW(), '4.2 Cost Optimization', true, 'Configuring `use_spot_instances=True` and `checkpoint_s3_uri` on SageMaker Estimators to leverage spare EC2 capacity at steep discounts.', 'MUST-KNOW EXAM RULE: When using Managed Spot Training, you MUST configure checkpointing in your training code and set `checkpoint_s3_uri`. Without checkpointing, interruptions force training to restart from scratch!'),
  ('mla-4-2-2', 'user-default', 'goal-aws', 'Cost-Effective Inference Strategies (Serverless, Multi-Model, Graviton Instances)', 'Domain 4: Operations & Security', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/best-practices-inference-cost.html', 25, false, NOW(), '4.2 Cost Optimization', true, 'Optimize hosting spend: Serverless Inference for intermittent bursts, Multi-Model Endpoints for hundreds of models, and Graviton instances for CPU workloads.', 'Quick Rule: If inference traffic drops to zero overnight, choose SageMaker Serverless Inference ($0 when idle) rather than paying 24/7 for dedicated instances.'),
  ('mla-4-2-3', 'user-default', 'goal-aws', 'Foundation Model Inference Cost Management (Token Optimization & Prompt Caching)', 'Domain 4: Operations & Security', 'Hard', 'https://docs.aws.amazon.com/bedrock/latest/userguide/prompt-caching.html', 30, false, NOW(), '4.2 Cost Optimization', true, 'Control Bedrock spending: optimize prompt token length, utilize Anthropic prompt caching for repeated document headers, and set token usage quotas.', 'Cost Optimization: Prompt Caching reduces input token processing costs by up to 80% on long repeated contexts (e.g., a 20-page legal contract queried multiple times).'),
  ('mla-4-2-4', 'user-default', 'goal-aws', 'Model Routing & Cascading (Haiku for Simple Tasks, Sonnet for Complex Queries)', 'Domain 4: Operations & Security', 'Hard', 'https://docs.aws.amazon.com/bedrock/latest/userguide/models-supported.html', 30, false, NOW(), '4.2 Cost Optimization', true, 'Implement a tiered model routing architecture to send easy queries to smaller models (Claude 3.5 Haiku) and escalate difficult reasoning to Claude 3.5 Sonnet.', 'Architectural Pattern: Use a fast, inexpensive classifier or Haiku to classify intent. 80% of queries get answered at 1/10th the cost; only the complex 20% route to Sonnet.'),
  ('mla-4-2-5', 'user-default', 'goal-aws', 'AWS Cost Governance Tools (AWS Budgets, Cost Allocation Tags & Cost Explorer)', 'Domain 4: Operations & Security', 'Easy', 'https://docs.aws.amazon.com/cost-management/latest/userguide/budgets-managing-costs.html', 20, false, NOW(), '4.2 Cost Optimization', false, 'Tag SageMaker resources (`Project`, `Environment`, `CostCenter`), configure AWS Budgets alarms, and analyze historical spend trends in Cost Explorer.', 'Exam Note: Use Cost Allocation Tags on SageMaker Training jobs and Endpoints to track which business team or experiment incurred the GPU spend.'),
  ('mla-4-3-1', 'user-default', 'goal-aws', 'IAM Execution Roles & Least-Privilege Policies for SageMaker & Bedrock', 'Domain 4: Operations & Security', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/sagemaker-roles.html', 35, false, NOW(), '4.3 Security & Compliance', true, 'Author precise IAM trust relationships and permissions policies granting SageMaker and Bedrock access strictly to specific S3 buckets and KMS keys.', 'Security Principle: Avoid `AdministratorAccess` or broad wildcards (`s3:*`). Grant `s3:GetObject` only to the training data bucket, `s3:PutObject` only to the model artifact bucket, and `kms:Decrypt` only on the specific CMK.'),
  ('mla-4-3-2', 'user-default', 'goal-aws', 'Data Encryption at Rest & In Transit (AWS KMS Customer Managed Keys & Inter-Container TLS)', 'Domain 4: Operations & Security', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/encryption-at-rest.html', 30, false, NOW(), '4.3 Security & Compliance', true, 'Configure AWS KMS Customer Managed Keys (CMKs) for S3 buckets, EBS storage volumes, and enable inter-container TLS encryption for distributed training nodes.', 'Security Rule: For distributed training across multiple instances, enable `EnableInterContainerTrafficEncryption=True` on the Estimator to encrypt peer-to-peer data transfers in transit.'),
  ('mla-4-3-3', 'user-default', 'goal-aws', 'Complete Network Isolation (Private Subnets, S3 Gateway Endpoints, EnableNetworkIsolation)', 'Domain 4: Operations & Security', 'Hard', 'https://docs.aws.amazon.com/sagemaker/latest/dg/mkt-algo-network-isolation.html', 35, false, NOW(), '4.3 Security & Compliance', true, 'Lock down ML training and inference containers by setting `EnableNetworkIsolation=True`, preventing training algorithms from making any external network calls.', 'Air-Gapped Training: When `EnableNetworkIsolation=True` is enabled, the training container has NO network interface and cannot make any HTTP/HTTPS calls outside the instance, preventing data exfiltration.'),
  ('mla-4-3-4', 'user-default', 'goal-aws', 'Amazon Bedrock Guardrails: Content Filtering, Denied Topics & Prompt Injection Defense', 'Domain 4: Operations & Security', 'Hard', 'https://docs.aws.amazon.com/bedrock/latest/userguide/guardrails.html', 35, false, NOW(), '4.3 Security & Compliance', true, 'Configure Bedrock Guardrails to block toxic content (hate, sexual, violence), enforce customized denied topics, and prevent prompt injection / jailbreak attacks.', 'TOP EXAM PRIORITY: Bedrock Guardrails can be applied to ANY foundation model on Bedrock and custom fine-tuned models. It evaluates both user input prompts and model generated completions.'),
  ('mla-4-3-5', 'user-default', 'goal-aws', 'Bedrock Guardrails: Sensitive Information PII Masking & Regex Filtering', 'Domain 4: Operations & Security', 'Hard', 'https://docs.aws.amazon.com/bedrock/latest/userguide/guardrails-sensitive-filters.html', 30, false, NOW(), '4.3 Security & Compliance', true, 'Detect, block, or automatically mask PII entities (SSN, credit card, phone, email) in LLM input queries and generated responses using Bedrock Guardrails.', 'Action Types in Guardrails: You can choose to either BLOCK the request with a standard message (''I cannot process requests containing sensitive PII'') or automatically ANONYMIZE/MASK the entity (e.g. `[EMAIL]`).'),
  ('mla-4-3-6', 'user-default', 'goal-aws', 'Auditing & Vulnerability Management (AWS CloudTrail, AWS Config, Amazon Inspector)', 'Domain 4: Operations & Security', 'Medium', 'https://docs.aws.amazon.com/sagemaker/latest/dg/logging-using-cloudtrail.html', 25, false, NOW(), '4.3 Security & Compliance', false, 'Audit all SageMaker and Bedrock API calls via AWS CloudTrail, evaluate KMS encryption rules via AWS Config, and scan custom ECR container images with Amazon Inspector.', 'Compliance Trio: CloudTrail audits WHO called WHAT API at WHEN. AWS Config tracks WHETHER resources comply with security policies. Amazon Inspector scans container images for CVE vulnerabilities.')
